def line_total(order):
    qty = order.get("qty", 0)
    return max(qty, 0) * order["unit"]


def build_report(orders, limit=100):
    total = 0
    codes = []
    for order in orders:
        if not order.get("active", False):
            continue
        amount = line_total(order)
        total += amount
        codes.append(order["sku"])
    if total >= limit:
        category = "bulk"
        total -= 10
    else:
        category = "standard"
    return {
        "total": total,
        "category": category,
        "codes": codes,
    }

def make_session():
    state = {"items": [], "calls": 0}

    def record(label):
        state["calls"] += 1
        state["items"].append(label)
        return state["calls"]

    return state, record


def revise(items):
    mirror = items
    mirror.append("queued")
    items = items + ["local"]
    items[0] = "draft"
    return items

def handle(value, events):
    events.append(f"start:{value}")
    try:
        if value is None:
            return {"status": "empty", "events": events}
        number = int(value)
        if number < 0:
            return {"status": "skip", "events": events}
        if number == 0:
            raise ValueError("zero")
        return {"status": "ok", "value": 12 // number, "events": events}
    except ValueError:
        events.append("invalid")
        return {"status": "invalid", "events": events}
    finally:
        events.append("end")


def collect(values):
    results = []
    events = []
    for value in values:
        item = handle(value, events)
        results.append(item)
    return results, events

def read_values(raw, trace):
    trace.append("open")
    try:
        for text in raw:
            trace.append(f"read:{text}")
            if text.startswith("#"):
                continue
            number = int(text)
            yield number
    finally:
        trace.append("close")


def take_until(values, limit):
    total = 0
    for number in values:
        if number > limit:
            return total
        total += number
    return total
